// Structure la candidature reçue (formulaire, job board ou email déjà converti en texte).
// Une information absente reste vide : elle n'est jamais devinée.
const c = $input.first().json.body ?? $input.first().json;
const texte = String(c.cv_texte ?? c.cv ?? '') + '\n' + String(c.lettre ?? '');
const chercher = (re) => (texte.match(re)?.[1] ?? '').trim();
const annees = chercher(/(\d{1,2})\s*(?:ans|années)\s+d['’]expérience/i);
const COMPETENCES = ['n8n', 'make', 'zapier', 'airtable', 'notion', 'python', 'javascript', 'sql', 'excel',
  'gestion de projet', 'anglais', 'crm', 'salesforce', 'hubspot', 'api'];
const competences = COMPETENCES.filter((k) => texte.toLowerCase().includes(k));
return [{ json: {
  nom: String(c.nom ?? '').trim(),
  email: String(c.email ?? '').trim(),
  poste: String(c.poste ?? '').trim(),
  anneesExperience: annees ? Number(annees) : null,
  competences,
  formation: chercher(/((?:master|licence|bac\s*\+\s*\d|bts|but|mba|rncp)[^\n.]{0,60})/i),
  mobilite: chercher(/mobilit[ée]\s*:?\s*([^\n.]{2,60})/i),
  texte,
  recuLe: new Date().toISOString(),
} }];

// Compare le profil aux critères du poste et produit un résumé structuré.
// Ce n'est JAMAIS une décision : le statut reste "À examiner par le recruteur".
// Critères à définir pour chaque poste. Le champ "promptIA" peut être envoyé à un LLM.
const CRITERES = {
  mustHave: ['gestion de projet', 'airtable'],
  niceToHave: ['n8n', 'make', 'api', 'anglais'],
  experienceMin: 1,
};
const p = $input.first().json;
const mustOk = CRITERES.mustHave.filter((k) => p.competences.includes(k));
const niceOk = CRITERES.niceToHave.filter((k) => p.competences.includes(k));
const expOk = p.anneesExperience === null ? null : p.anneesExperience >= CRITERES.experienceMin;
const score = Math.round(
  (mustOk.length / CRITERES.mustHave.length) * 60 +
  (niceOk.length / CRITERES.niceToHave.length) * 25 +
  (expOk ? 15 : 0));
const manquants = CRITERES.mustHave.filter((k) => !mustOk.includes(k));
const questions = [
  ...manquants.map((k) => `Pouvez-vous décrire une expérience liée à : ${k} ?`),
  ...(expOk === null ? ['Combien d’années d’expérience avez-vous sur ce type de poste ?'] : []),
  ...(!p.mobilite ? ['Quelle est votre mobilité géographique ?'] : []),
  'Quel projet récent illustre le mieux votre façon de travailler ?',
];
return [{ json: {
  ...p,
  scoreCorrespondance: score,
  resume: `Must-have : ${mustOk.length}/${CRITERES.mustHave.length}${manquants.length ? ` (manque : ${manquants.join(', ')})` : ''}. ` +
    `Nice-to-have : ${niceOk.join(', ') || 'aucun'}. Expérience : ${p.anneesExperience ?? 'non précisée'} an(s).`,
  questionsEntretien: questions.join('\n'),
  statut: 'À examiner par le recruteur',
  promptIA: `Résume ce profil en 5 lignes par rapport aux critères ${JSON.stringify(CRITERES)}. N'émets aucune décision.\n${p.texte.slice(0, 4000)}`,
} }];
